SETTINGS = ("skin_tone_match", "face_stabilization", "hair_transfer", "hide_real_hair")
BACKUP_PREFIX = "backup_smoother_swap_"


def say(msg=""):
    print(msg, flush=True)


def norm(b: bytes) -> bytes:
    return b.replace(b"\r\n", b"\n")


def sha(b: bytes) -> str:
    return hashlib.sha256(norm(b)).hexdigest()


def is_dlc(folder: str) -> bool:
    return os.path.isfile(os.path.join(folder, "modules", "globals.py")) and \
        os.path.isfile(os.path.join(folder, "modules", "processors", "frame", "face_swapper.py"))


def find_root() -> str:
    here = os.path.dirname(os.path.abspath(__file__))
    for cand in (here, os.getcwd(), os.path.dirname(here)):
        if is_dlc(cand):
            return cand
    for name in os.listdir(here):
        cand = os.path.join(here, name)
        if os.path.isdir(cand) and is_dlc(cand):
            return cand
    while True:
        path = input("Where is your Deep-Live-Cam folder? (paste the path) ").strip().strip('"')
        if is_dlc(path):
            return path
        say("That folder doesn't look like Deep-Live-Cam (no modules/globals.py). Try again.")


def uses_crlf(data: bytes) -> bool:
    return b"\r\n" in data


def write_file(path: str, content: bytes, crlf: bool) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if crlf:
        content = norm(content).replace(b"\n", b"\r\n")
    with open(path, "wb") as f:
        f.write(content)


def git_available(root: str) -> bool:
    try:
        subprocess.run(["git", "--version"], capture_output=True, check=True)
        return True
    except Exception:
        return False


FILES = []
PATCH = ""


def classify(root: str, files):
    plan, already, conflicts = [], [], []
    for path, orig_sha, new_sha, data in files:
        full = os.path.join(root, path)
        current = open(full, "rb").read() if os.path.exists(full) else None
        if current is not None and sha(current) == new_sha:
            already.append(path)
        elif (current is None and orig_sha is None) or (current is not None and sha(current) == orig_sha):
            plan.append((path, current, data))
        else:
            conflicts.append(path)
    return plan, already, conflicts


def pick_variant(root: str) -> None:
    """Choose the build of the update that matches this Deep-Live-Cam version."""
    global FILES, PATCH
    best = None
    for label, files, patch in VARIANTS:
        _p, _a, conflicts = classify(root, files)
        # fewest conflicts first; on a tie, the build that covers the most files
        key = (len(conflicts), -len(files))
        if best is None or key < best[0]:
            best = (key, label, files, patch)
    _k, label, FILES, PATCH = best
    say(f"Matching your copy: {label}")


def try_git_apply(root: str) -> bool:
    """Merge the changes into files the user edited, if git can do it cleanly."""
    if not git_available(root):
        return False
    patch = zlib.decompress(base64.b64decode(PATCH))
    fd, ppath = tempfile.mkstemp(suffix=".patch")
    with os.fdopen(fd, "wb") as f:
        f.write(patch)
    try:
        for args in (["apply", "--check", "--whitespace=nowarn"],
                     ["apply", "--check", "--ignore-whitespace", "--whitespace=nowarn"]):
            r = subprocess.run(["git", *args, ppath], cwd=root, capture_output=True)
            if r.returncode == 0:
                subprocess.run(["git", *[a for a in args if a != "--check"], ppath],
                               cwd=root, check=True, capture_output=True)
                return True
        return False
    finally:
        os.remove(ppath)


def enable_settings(root: str) -> None:
    path = os.path.join(root, "switch_states.json")
    if not os.path.exists(path):
        return  # defaults are already "on"
    try:
        with open(path, "r") as f:
            state = json.load(f)
        for k in SETTINGS:
            state[k] = True
        with open(path, "w") as f:
            json.dump(state, f)
    except Exception as e:
        say(f"  (could not update switch_states.json: {e}; the switches are on by default anyway)")


def verify(root: str) -> bool:
    ok = True
    if not FILES:
        pick_variant(root)
    for path, _o, _n, _d in FILES:
        if path.endswith(".py"):
            try:
                py_compile.compile(os.path.join(root, path), doraise=True)
            except py_compile.PyCompileError as e:
                say(f"  ERROR: {path} does not compile: {e.msg}")
                ok = False
    if not ok:
        return False
    say("  All files compile.")
    for test in ("tests/test_live_tracking_and_skin_tone.py", "tests/test_hair_transfer.py"):
        r = subprocess.run([sys.executable, test], cwd=root, capture_output=True, text=True)
        tail = (r.stderr or r.stdout).strip().splitlines()[-1:] or [""]
        if r.returncode == 0:
            say(f"  Self-test {os.path.basename(test)}: passed")
        else:
            say(f"  Self-test {os.path.basename(test)}: FAILED ({tail[0]})")
            say("  " + "\n  ".join((r.stderr or r.stdout).strip().splitlines()[-8:]))
            ok = False
    return ok


def install(root: str) -> int:
    say(f"Deep-Live-Cam folder: {root}")
    pick_variant(root)
    say("")
    plan, already, conflicts = classify(root, FILES)
    plan = [(p, cur, zlib.decompress(base64.b64decode(d))) for p, cur, d in plan]

    if not plan and not conflicts:
        say("Already installed -- nothing to do.")
        enable_settings(root)
        return 0 if verify(root) else 1

    backup = os.path.join(root, BACKUP_PREFIX + time.strftime("%Y%m%d-%H%M%S"))
    os.makedirs(backup)
    manifest = {"created": [], "replaced": []}

    def backup_file(path):
        full = os.path.join(root, path)
        if os.path.exists(full):
            dst = os.path.join(backup, path)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(full, dst)
            manifest["replaced"].append(path)
        else:
            manifest["created"].append(path)

    if conflicts:
        say("These files were changed from the original Deep-Live-Cam version:")
        for c in conflicts:
            say(f"  - {c}")
        say("Trying to merge the update into them with git...")
        for path, _o, _n, _d in FILES:
            backup_file(path)
        if try_git_apply(root):
            say("  Merged cleanly.")
        else:
            shutil.rmtree(backup, ignore_errors=True)
            say("\nNOTHING WAS CHANGED: the update can't be merged automatically into your edited")
            say("files. Send the files listed above to Claude and it can make a version for your copy.")
            return 2
    else:
        for path, current, new in plan:
            backup_file(path)
            write_file(os.path.join(root, path), new, uses_crlf(current) if current else os.name == "nt")
        for path in already:
            pass
    with open(os.path.join(backup, "manifest.json"), "w") as f:
        json.dump(manifest, f, indent=1)

    say(f"Installed. Old files saved in: {backup}")
    enable_settings(root)
    say("\nChecking the installation...")
    ok = verify(root)
    say("")
    if ok:
        say("Done. Start Deep-Live-Cam as usual. In Options, 'Match Skin Tone', 'Stabilize Face',")
        say("'Use Source Hair' and 'Hide My Hair' are on. Tip: when Live starts, step out of view")
        say("for a second so it can learn your background.")
    else:
        say("Installed, but a check failed (see above). To undo: run this installer with --undo")
    return 0 if ok else 1


def undo(root: str) -> int:
    backups = sorted(d for d in os.listdir(root) if d.startswith(BACKUP_PREFIX))
    if not backups:
        say("No backup found -- nothing to undo.")
        return 1
    backup = os.path.join(root, backups[-1])
    with open(os.path.join(backup, "manifest.json")) as f:
        manifest = json.load(f)
    for path in manifest["replaced"]:
        shutil.copy2(os.path.join(backup, path), os.path.join(root, path))
    for path in manifest["created"]:
        full = os.path.join(root, path)
        if os.path.exists(full):
            os.remove(full)
        # remove folders the installer created (only if now empty)
        d = os.path.dirname(full)
        while os.path.abspath(d) != os.path.abspath(root):
            leftovers = [x for x in os.listdir(d) if x != "__pycache__"] if os.path.isdir(d) else ["x"]
            if leftovers:
                break
            shutil.rmtree(d, ignore_errors=True)
            d = os.path.dirname(d)
    say(f"Restored the files from {backup}.")
    return 0


def main() -> int:
    say("Deep-Live-Cam smoother live swap installer\n")
    root = find_root()
    if "--undo" in sys.argv:
        return undo(root)
    return install(root)


if __name__ == "__main__":
    code = 1
    try:
        code = main()
    except KeyboardInterrupt:
        say("\nCancelled.")
    except Exception as e:
        say(f"\nUnexpected error: {e}\nNothing more was changed. Send this message to Claude.")
    if os.name == "nt" and sys.stdin and sys.stdin.isatty() and "--no-pause" not in sys.argv:
        input("\nPress Enter to close...")
    sys.exit(code)
